function invoiceLineHtml(it={}){return '<div class="invoice-line"><div class="invoice-identity-grid"><label>Design Number<input name="item_design_number[]" value="'+esc(it.designNumber||it.itemNumber||'')+'" placeholder="Design / style number"></label><label>Category<input name="item_category[]" value="'+esc(it.category||'')+'" placeholder="Category"></label><label>Colour<input name="item_colour[]" value="'+esc(it.colour||'')+'" placeholder="Colour"></label><label>Size<input name="item_size[]" value="'+esc(it.size||'')+'" placeholder="Size"></label></div><label>Item / Description<input name="item_name[]" required value="'+esc(it.name||'')+'" placeholder="Garment / style"></label><div class="invoice-line-grid"><label>HSN/SAC<input name="item_hsn[]" inputmode="numeric" pattern="[0-9]{4}|[0-9]{6}|[0-9]{8}" required value="'+esc(it.hsn||'')+'" placeholder="4, 6 or 8 digits"></label><label>Qty<input name="item_qty[]" type="number" min="0.001" step="0.001" required value="'+esc(it.qty||1)+'"></label><label>Piece Amount ₹<input name="item_rate[]" type="number" min="0" step="0.01" required value="'+esc(it.rate||'')+'" placeholder="0.00"></label><label>Discount ₹<input name="item_discount[]" type="number" min="0" step="0.01" value="'+esc(it.discount||0)+'"></label><label>GST %<input name="item_gst[]" type="number" min="0" max="100" step="0.01" required value="'+esc(it.gst??'')+'" placeholder="GST %"></label></div><button type="button" class="removeitem" data-invoice-remove>Remove item</button></div>';}
function taxInvoicesPage(){const p=invoiceProfile,order=invoicePrefillOrder,d=new Date().toISOString().slice(0,10),next=invoiceNumber(d).number,prefill=((invoicePrefillSlip&&invoicePrefillSlip.items)||(order&&order.items)||[]).map(it=>({name:it.name||it.style||'Garment',designNumber:it.designNumber||it.itemNumber||'',category:it.category||it.model||'',colour:it.colour||'',size:it.size||'',qty:it.qty||1,rate:it.rate||'',gst:5})),rows=prefill.length?prefill:[{}];return '<div class="heading"><div><small>BILLING & GST</small><h2>GST Tax Invoices</h2></div><span class="tag">LOCAL RECORDS</span></div>'+card('Create GST tax invoice','Enter your registered business details and invoice items. Amounts and GST are calculated on this device.','<form id="invoiceform"><div class="invoice-section-title">Supplier / Your business</div><label>Business legal name<input name="seller_name" required value="'+esc(p.name||'Prasad Apparels')+'"></label><label>Business address<textarea name="seller_address" required rows="2" placeholder="Registered business address">'+esc(p.address||'')+'</textarea></label><div class="two"><label>Supplier GSTIN<input name="seller_gstin" maxlength="15" required value="'+esc(p.gstin||'')+'" placeholder="15-character GSTIN"></label><label>State<input name="seller_state" required value="'+esc(p.state||'Maharashtra')+'" placeholder="e.g. Maharashtra"></label></div><div class="invoice-section-title">Invoice & customer</div><div class="two"><label>Invoice number<input name="invoice_no" required value="'+esc(next)+'"></label><label>Invoice date<input name="invoice_date" type="date" required value="'+d+'"></label><label>Payment due date<input name="due_date" type="date" required value="'+new Date(new Date(d+'T12:00:00').getTime()+30*86400000).toISOString().slice(0,10)+'"></label></div><label>No. of Packages (Cartons)<input name="carton_count" type="number" min="1" step="1" required value="1"></label><label>Customer / Buyer name<input name="buyer_name" required value="'+esc(order&&order.party||'')+'" placeholder="Customer name"></label><label>Buyer address<textarea name="buyer_address" rows="2" placeholder="Billing address"></textarea></label><div class="two"><label>Buyer mobile<input name="buyer_mobile" inputmode="tel" maxlength="15" placeholder="Customer mobile number"></label><label>PIN code<input name="buyer_pin" inputmode="numeric" maxlength="10" placeholder="Delivery PIN code"></label></div><div class="two"><label>Buyer GSTIN (if registered)<input name="buyer_gstin" maxlength="15" placeholder="15-character GSTIN"></label><label>Place of supply / State<input name="place_supply" required value="'+esc(p.state||'Maharashtra')+'" placeholder="State"></label></div><div class="invoice-section-title">Items & GST</div><div id="invoice-lines">'+rows.map(invoiceLineHtml).join('')+'</div><button type="button" class="secondary" id="invoice-add-line">＋ Add another item</button><label>Notes / Terms<textarea name="invoice_notes" rows="2" placeholder="Payment terms, delivery notes..."></textarea></label><button class="primary" type="submit">Save GST Tax Invoice</button><p class="hint">Local draft only. Verify GSTIN, HSN, place of supply and applicable tax rate before issuing. This is a device-local invoice record; shared storage and production controls are still being built.</p></form>')+card('Saved tax invoices',taxInvoices.length+' invoices on this device',taxInvoices.length?taxInvoices.slice().reverse().map(v=>'<div class="line invoice-saved"><div><b>'+esc(v.invoice_no)+'</b><small>'+esc(v.buyer_name)+' · '+esc(v.invoice_date)+' · Due '+esc(v.due_date||v.invoice_date)+' · '+money(v.grand_total)+' · '+(v.status==='reversed'?'REVERSED':'ACTIVE')+'</small></div><div class="invoice-actions">'+(v.status==='reversed'?'<span class="tag">REVERSED</span>':'<button class="secondary" data-print-invoice="'+esc(v.id)+'">Print</button><button class="secondary" data-share-invoice="'+esc(v.id)+'">Share</button><button class="secondary" data-cancel-invoice="'+esc(v.id)+'">Cancel invoice</button>')+'</div></div>').join(''):'<div class="empty compact">No tax invoices created yet.</div>');}
const GST_STATE_CODES={'01':['jammu and kashmir','jk'],'02':['himachal pradesh','hp'],'03':['punjab','pb'],'04':['chandigarh','ch'],'05':['uttarakhand','uk'],'06':['haryana','hr'],'07':['delhi','new delhi','dl'],'08':['rajasthan','rj'],'09':['uttar pradesh','up'],'10':['bihar','br'],'11':['sikkim','sk'],'12':['arunachal pradesh','ar'],'13':['nagaland','nl'],'14':['manipur','mn'],'15':['mizoram','mz'],'16':['tripura','tr'],'17':['meghalaya','ml'],'18':['assam','as'],'19':['west bengal','wb'],'20':['jharkhand','jh'],'21':['odisha','orissa','od'],'22':['chhattisgarh','cg'],'23':['madhya pradesh','mp'],'24':['gujarat','gj'],'26':['dadra and nagar haveli and daman and diu','dnh'],'27':['maharashtra','mh'],'29':['karnataka','ka'],'30':['goa','ga'],'31':['lakshadweep','ld'],'32':['kerala','kl'],'33':['tamil nadu','tn'],'34':['puducherry','pondicherry','py'],'35':['andaman and nicobar islands','an'],'36':['telangana','ts'],'37':['andhra pradesh','ap'],'38':['ladakh','la']};
function gstStateCode(value){const raw=String(value||'').trim().toLowerCase(),prefix=raw.match(/^(\d{2})(?:\b|\s|[-(:])/);if(prefix&&GST_STATE_CODES[prefix[1]])return prefix[1];const normal=raw.replace(/[^a-z]/g,'');for(const [code,names] of Object.entries(GST_STATE_CODES))if(names.some(n=>n.replace(/[^a-z]/g,'')===normal))return code;return '';}
function calculateInvoice(form){const names=form.getAll('item_name[]'),designNumbers=form.getAll('item_design_number[]'),categories=form.getAll('item_category[]'),colours=form.getAll('item_colour[]'),sizes=form.getAll('item_size[]'),hsns=form.getAll('item_hsn[]'),qtys=form.getAll('item_qty[]'),rates=form.getAll('item_rate[]'),discounts=form.getAll('item_discount[]'),gsts=form.getAll('item_gst[]'),sellerGstin=String(form.get('seller_gstin')||'').trim().toUpperCase(),sellerState=String(form.get('seller_state')||'').trim().toLowerCase(),place=String(form.get('place_supply')||'').trim().toLowerCase(),sellerCode=sellerGstin.slice(0,2),placeCode=gstStateCode(place),stateCodeMatch=/^\d{2}$/.test(sellerCode)&&!!GST_STATE_CODES[sellerCode]&&!!placeCode,intra=stateCodeMatch?sellerCode===placeCode:(!!sellerState&&sellerState===place);const items=names.map((name,i)=>{const qty=Number(qtys[i]||0),rate=Number(rates[i]||0),discount=Number(discounts[i]||0),gst=Number(gsts[i]||0),taxable=Math.max(0,qty*rate-discount),tax=taxable*gst/100;return {name,designNumber:designNumbers[i]||'',itemNumber:designNumbers[i]||'',category:categories[i]||'',colour:colours[i]||'',size:sizes[i]||'',hsn:hsns[i]||'',qty,rate,discount,gst,taxable,tax,cgst:intra?tax/2:0,sgst:intra?tax/2:0,igst:intra?0:tax};}).filter(x=>x.name&&x.qty>0);const taxable=items.reduce((n,x)=>n+x.taxable,0),cgst=items.reduce((n,x)=>n+x.cgst,0),sgst=items.reduce((n,x)=>n+x.sgst,0),igst=items.reduce((n,x)=>n+x.igst,0),total=taxable+cgst+sgst+igst;return {items,taxable,cgst,sgst,igst,grand_total:Math.round((total+Number.EPSILON)*100)/100,intra};}
function validateInvoiceDraft(totals,form){
 const sellerState=String(form.get('seller_state')||'').trim(),place=String(form.get('place_supply')||'').trim(),sellerGstin=String(form.get('seller_gstin')||'').trim().toUpperCase();
 if(!sellerState||!place)return 'Enter both seller state and place of supply.';
 if(!/^\d{2}[0-9A-Z]{13}$/.test(sellerGstin))return 'Supplier GSTIN must start with a 2-digit GST state code and contain 15 characters. Confirm the GSTIN with your CA.';
 const sellerCode=sellerGstin.slice(0,2),knownSellerState=gstStateCode(sellerState),knownPlaceState=gstStateCode(place);
 if(!GST_STATE_CODES[sellerCode])return 'Supplier GSTIN has an unrecognised state code. Confirm the GSTIN with your CA before saving.';
 if(!knownSellerState)return 'Seller state is not recognised in the GST state list. Select a recognised Indian state or Union Territory before saving.';
 if(knownSellerState!==sellerCode)return 'Supplier GSTIN state code does not match the selected seller state. Check the GSTIN and state before saving.';
 if(!knownPlaceState)return 'Place of supply is not recognised in the GST state list. Enter the state or Union Territory name/code and confirm it with your CA before saving.';
 if(!totals.items.length)return 'Add at least one valid invoice item.';
 const names=form.getAll('item_name[]'),hsns=form.getAll('item_hsn[]'),qtys=form.getAll('item_qty[]'),rates=form.getAll('item_rate[]'),discounts=form.getAll('item_discount[]'),gsts=form.getAll('item_gst[]');
 for(let i=0;i<names.length;i++){
  if(!String(names[i]||'').trim())return 'Item '+(i+1)+': enter the garment / item description.';
  const h=String(hsns[i]||'').trim();
  if(!/^(?:[0-9]{4}|[0-9]{6}|[0-9]{8})$/.test(h))return 'Item '+(i+1)+': enter a valid 4, 6 or 8 digit HSN/SAC code. Confirm the correct code with your CA.';
  const q=Number(qtys[i]),r=Number(rates[i]),d=Number(discounts[i]||0),g=Number(gsts[i]);
  if(!Number.isFinite(q)||q<=0)return 'Item '+(i+1)+': quantity must be greater than zero.';
  if(!Number.isFinite(r)||r<0)return 'Item '+(i+1)+': piece amount cannot be negative.';
  if(!Number.isFinite(d)||d<0||d>q*r)return 'Item '+(i+1)+': discount must be between zero and the gross line amount.';
  if(!Number.isFinite(g)||g<0||g>100)return 'Item '+(i+1)+': enter a GST rate from 0 to 100.';
 }
 const mobile=String(form.get('buyer_mobile')||'').replace(/[\s()+-]/g,'');
 if(mobile&&!/^\d{10,15}$/.test(mobile))return 'Enter a valid buyer mobile number (10 to 15 digits), or leave it blank.';
 const pin=String(form.get('buyer_pin')||'').trim();
 if(pin&&!/^\d{6}$/.test(pin))return 'Enter a valid 6-digit PIN code, or leave it blank.';
 const cartons=Number(form.get('carton_count')||1);
 if(!Number.isInteger(cartons)||cartons<1)return 'Number of cartons must be a whole number of at least 1.';
 return '';
}

function cancelTaxInvoice(id){
 const v=taxInvoices.find(x=>x.id===id);if(!v||v.status==='reversed'){alert('Invoice is not active.');return;}
 const readRows=k=>{try{const x=JSON.parse(localStorage.getItem(k)||'[]');return Array.isArray(x)?x:[]}catch(_){return []}};
 const dispatched=readRows('pa_dispatches_v1').some(x=>x.invoiceId===id),receipts=readRows('pa_customer_receipts_v1'),paid=receipts.some(x=>x.invoiceId===id||(x.allocations||[]).some(a=>a.invoiceId===id&&Number(a.amount||0)>0)),credits=arCreditNotes.some(x=>x.invoiceId===id&&x.status!=='reversed'),returns=readRows('pa_sales_returns_v1').some(x=>x.invoiceId===id&&x.status!=='cancelled');
 if(dispatched||paid||credits||returns){alert('Cancellation blocked: this invoice has dispatch, receipt/payment, credit-note or return activity. Use the approved reversal/credit-note workflow and CA review.');return;}
 const reason=prompt('Reason for cancelling invoice '+v.invoice_no+':');if(!reason||!reason.trim())return;
 if(!confirm('Cancel '+v.invoice_no+'? The number will remain in the register as REVERSED; the record will not be deleted.'))return;
 v.status='reversed';v.reversedAt=new Date().toISOString();v.reversalReason=reason.trim();v.reversedBy='Local user — identity not verified';localStorage.setItem('pa_tax_invoices',JSON.stringify(taxInvoices));render();alert('Invoice marked reversed. No dispatch stock issue was posted. Keep the cancellation record for CA review.');
}
