function printTaxInvoice(id){const v=taxInvoices.find(x=>x.id===id);if(!v){alert('Invoice not found.');return;}const rows=v.items.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+esc(x.designNumber||x.itemNumber||'')+'</td><td>'+esc(x.category||'')+'</td><td>'+esc(x.colour||'')+'</td><td>'+esc(x.size||'')+'</td><td>'+esc(x.hsn)+'</td><td>'+x.qty+'</td><td>'+money(x.rate)+'</td><td>'+money(x.discount)+'</td><td>'+x.gst+'%</td><td>'+money(x.taxable)+'</td><td>'+money(x.tax)+'</td></tr>').join('');const w=window.open('','_blank');if(!w){alert('Allow pop-ups to print the invoice.');return;}w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>'+esc(v.invoice_no)+'</title><style>body{font:13px Arial;color:#222;margin:24px}h1{text-align:center;font-size:21px}h2{font-size:16px;margin:0 0 8px}.copy-label{text-align:center;border:1px solid #555;padding:7px;font-weight:bold;letter-spacing:.5px;margin-bottom:10px}.top{display:flex;justify-content:space-between;gap:20px}.panel{border:1px solid #bbb;padding:12px;margin:10px 0;flex:1}table{width:100%;border-collapse:collapse;margin-top:16px}th,td{border:1px solid #bbb;padding:7px;text-align:left;font-size:11px}th{background:#f2f2f2}.totals{margin:18px 0 0 auto;width:280px}.totals div{display:flex;justify-content:space-between;padding:5px;border-bottom:1px solid #ddd}.grand{font-weight:bold;font-size:16px}.foot{margin-top:45px;display:flex;justify-content:space-between}.muted{color:#555;font-size:11px}@media print{body{margin:10mm}}</style></head><body><div class="copy-label">ORIGINAL FOR RECIPIENT</div><h1>TAX INVOICE</h1><div class="top"><div class="panel"><h2>'+esc(v.seller_name)+'</h2>'+esc(v.seller_address).replace(/\n/g,'<br>')+'<p>GSTIN: '+esc(v.seller_gstin||'Not entered')+'</p><b>State:</b> '+esc(v.seller_state)+'</div><div class="panel"><b>Invoice No:</b> '+esc(v.invoice_no)+'<br><b>Date:</b> '+esc(v.invoice_date)+'<br><b>No. of Packages (Cartons):</b> '+Math.max(1,Number(v.carton_count||1))+'<br><b>Place of Supply:</b> '+esc(v.place_supply)+'</div></div><div class="panel"><b>Bill To:</b><h2>'+esc(v.buyer_name)+'</h2>'+esc(v.buyer_address||'').replace(/\n/g,'<br>')+'<p>Mobile: '+esc(v.buyer_mobile||'Not provided')+' · PIN: '+esc(v.buyer_pin||'Not provided')+'</p><p>GSTIN: '+esc(v.buyer_gstin||'Unregistered / not provided')+'</p></div><table><thead><tr><th>Description</th><th>Design No.</th><th>Category</th><th>Colour</th><th>Size</th><th>HSN Code</th><th>Qty (Pcs)</th><th>Piece Amount</th><th>Discount</th><th>GST</th><th>Taxable</th><th>Tax</th></tr></thead><tbody>'+rows+'</tbody></table><div class="totals"><div><span>Taxable value</span><b>'+money(v.taxable)+'</b></div><div><span>CGST</span><b>'+money(v.cgst)+'</b></div><div><span>SGST</span><b>'+money(v.sgst)+'</b></div><div><span>IGST</span><b>'+money(v.igst)+'</b></div><div class="grand"><span>Total</span><b>'+money(v.grand_total)+'</b></div></div><p>Notes: '+esc(v.invoice_notes||'')+'</p><div class="foot"><span class="muted">Subject to verification of GST and invoice particulars.</span><b>Authorised Signatory</b></div><script>window.onload=()=>window.print()<\/script></body></html>');w.document.close();}
async function shareTaxInvoice(id){const v=taxInvoices.find(x=>x.id===id);if(!v){alert('Invoice not found.');return;}const text=invoiceShareText(v);if(navigator.share){try{await navigator.share({title:'GST Tax Invoice '+v.invoice_no,text});return;}catch(e){if(e&&e.name==='AbortError')return;}}window.open('https://wa.me/?text='+encodeURIComponent(text),'_blank','noopener');}

