function orderLinesHtml(){if(!orderItems.length)return '<div class="empty compact">Scan a garment barcode to add your first item.</div>';return orderItems.map((it,i)=>'<div class="orderline"><div class="orderproduct"><b>'+esc(it.name||'Scanned item')+'</b><small>Barcode: '+esc(it.code)+'</small><div class="two"><label>Item Number<input data-item-number="'+i+'" value="'+esc(it.itemNumber||'')+'" placeholder="Item number"></label><label>Category<input data-category="'+i+'" value="'+esc(it.category||'')+'" placeholder="Category"></label><label>Colour<input data-colour="'+i+'" value="'+esc(it.colour||'')+'" placeholder="Colour"></label><label>Size<input data-size="'+i+'" value="'+esc(it.size||'')+'" placeholder="Size"></label></div><input data-name="'+i+'" value="'+esc(it.name||'')+'" placeholder="Product description / style" aria-label="Product description"></div><div class="orderqty"><small>Qty</small><div><button type="button" data-qty="'+i+'" data-delta="-1">−</button><b>'+it.qty+'</b><button type="button" data-qty="'+i+'" data-delta="1">+</button></div></div><button type="button" class="removeitem" data-remove="'+i+'">×</button></div>').join('')}
function addScannedBarcode(code){code=String(code||'').trim();if(!code)return;let item=orderItems.find(x=>x.code===code);if(item)item.qty++;else{const m=barcodeCatalog()[code]||{};const name=[m.style,m.colour,m.size?'Size '+m.size:''].filter(Boolean).join(' · ');orderItems.push({code,name,itemNumber:m.itemNumber||m.itemNo||m.styleNumber||m.style||'',category:m.category||'',style:m.style||'',model:m.model||'',colour:m.colour||'',size:m.size||'',qty:1,rate:0});}render();const input=document.getElementById('manualbarcode');if(input)input.focus()}
async function startBarcodeScanner(){const box=document.getElementById('scannerbox');box.hidden=false;const start=document.getElementById('startscan');start.disabled=true;try{if(!window.Html5Qrcode){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/html5-qrcode@2.3.8/html5-qrcode.min.js';script.onload=resolve;script.onerror=()=>reject(new Error('Scanner library could not load. Use manual barcode entry.'));document.head.appendChild(script);});}scanner=new Html5Qrcode('reader');await scanner.start({facingMode:'environment'},{fps:12,qrbox:{width:260,height:130},formatsToSupport:[Html5QrcodeSupportedFormats.CODE_128,Html5QrcodeSupportedFormats.EAN_13,Html5QrcodeSupportedFormats.EAN_8,Html5QrcodeSupportedFormats.UPC_A,Html5QrcodeSupportedFormats.UPC_E,Html5QrcodeSupportedFormats.QR_CODE]},decoded=>{stopBarcodeScanner().then(()=>addScannedBarcode(decoded));},()=>{});}catch(e){alert('Could not start camera scanner: '+e.message+' You can enter the barcode manually.');box.hidden=true;}finally{start.disabled=false;}}
async function stopBarcodeScanner(){if(scanner){try{await scanner.stop();scanner.clear();}catch(e){}scanner=null;}const box=document.getElementById('scannerbox');if(box)box.hidden=true;}
const GARMENT_STOCK_KEY='pa_garment_stock_ledger_v1';
let garmentStockMoves=(()=>{try{const x=JSON.parse(localStorage.getItem(GARMENT_STOCK_KEY)||'[]');return Array.isArray(x)?x:[]}catch(e){return []}})();
const STOCK_IN_TYPES=['Opening balance','Production receipt','Purchase inward','Customer return'];
function stockBalanceRows(){
 const map=new Map();
 garmentStockMoves.forEach(m=>{const key=[m.style,m.colour||'',m.size||''].join('¦');if(!map.has(key))map.set(key,{style:m.style,colour:m.colour||'',size:m.size||'',available:0,quarantined:0,moves:0,lastDate:m.date||''});const r=map.get(key);const q=Number(m.qty||0);if(m.type==='Dispatch / sale issue'||m.type==='Stock adjustment out')r.available-=q;else if(m.type==='Customer return'&&m.status!=='released')r.quarantined+=q;else r.available+=q;r.moves++;if((m.date||'')>r.lastDate)r.lastDate=m.date||'';});
 return [...map.values()].sort((a,b)=>a.style.localeCompare(b.style)||a.colour.localeCompare(b.colour)||a.size.localeCompare(b.size));
}
function inventoryMigrationPreviewCard(){
 const api=typeof PAInventoryLedger!=='undefined'?PAInventoryLedger:null;
 if(!api||typeof api.preview!=='function')return '';
 let materials=[];try{const x=JSON.parse(localStorage.getItem('pa_stock_moves_v1')||'[]');materials=Array.isArray(x)?x:[]}catch(_){}
 const report=api.preview(garmentStockMoves,materials),garment=report.records.filter(x=>x.domain==='finished-garment').length,material=report.records.filter(x=>x.domain==='material').length;
 let dispatchAudit=null;
 if(typeof PADispatchAudit!=='undefined'&&typeof PADispatchAudit.auditDispatches==='function'&&typeof paDispatches!=='undefined'&&typeof taxInvoices!=='undefined')dispatchAudit=PADispatchAudit.auditDispatches(paDispatches,taxInvoices,garmentStockMoves);
 const dispatchDetails=dispatchAudit?'<div class="line"><span>Dispatches checked</span><b>'+dispatchAudit.dispatches+'</b></div><div class="line"><span>Expected dispatch stock issues</span><b>'+dispatchAudit.expectedIssues+'</b></div><div class="line"><span>Dispatch reconciliation issues</span><b>'+dispatchAudit.issues.length+'</b></div>'+(dispatchAudit.issues.length?'<ul>'+dispatchAudit.issues.slice(0,8).map(x=>'<li>'+esc(x.code)+' · '+esc(x.reference||x.dispatchId||'Review record')+'</li>').join('')+'</ul>':'<p class="hint">All auditable full / partial dispatch stock references match.</p>'):'';
 const details='<div class="metricgrid"><article class="metric"><small>Garment rows</small><b>'+garment+'</b></article><article class="metric"><small>Material rows</small><b>'+material+'</b></article><article class="metric"><small>Needs review</small><b>'+(report.invalid.length+report.duplicates.length+report.unallocated)+'</b></article></div>'+
 '<div class="line"><span>Invalid movements</span><b>'+report.invalid.length+'</b></div><div class="line"><span>Repeated legacy IDs</span><b>'+report.duplicates.length+'</b></div><div class="line"><span>Garment rows missing style / colour / size</span><b>'+report.unallocated+'</b></div>'+
 (dispatchAudit?'<h4>Dispatch stock reconciliation</h4>'+dispatchDetails:'')+
 '<p class="hint">'+esc(report.warning)+'</p><p class="hint">This screen reads existing browser records only. It does not import, rewrite, delete, or change stock balances. Legacy-unverified dispatches remain flagged for manual review.</p>';
 return card('Inventory migration preview','Read-only check before any stock-ledger consolidation.',details);
}
function stock(){
 const rows=stockBalanceRows(),total=rows.reduce((n,r)=>n+r.available,0),quarantine=rows.reduce((n,r)=>n+r.quarantined,0),low=rows.filter(r=>r.available<=Number(r.reorderLevel||0));
 return '<div class="heading"><div><small>INVENTORY CONTROL</small><h2>Garment stock</h2></div><span class="tag">'+rows.length+' VARIANTS</span></div>'+
 '<div class="metricgrid"><article class="metric"><small>Saleable pieces</small><b>'+total+'</b></article><article class="metric"><small>Return quarantine</small><b>'+quarantine+'</b></article><article class="metric"><small>Low / zero stock</small><b>'+low.length+'</b></article></div>'+
 card('Post stock movement','Every entry is a traceable ledger movement. Dispatch / sale issue reduces available stock; customer returns remain quarantined until inspected and released.','<form id="garment-stock-form"><div class="two"><label>Movement type<select name="type">'+['Opening balance','Production receipt','Purchase inward','Dispatch / sale issue','Customer return','Stock adjustment in','Stock adjustment out'].map(x=>'<option>'+x+'</option>').join('')+'</select></label><label>Date<input name="date" type="date" required value="'+new Date().toISOString().slice(0,10)+'"></label></div><div class="two"><label>Design / style number<input name="style" required placeholder="e.g. PA-101"></label><label>Garment description<input name="description" placeholder="Boys kurta set"></label></div><div class="two"><label>Colour<input name="colour" placeholder="Peach"></label><label>Size<input name="size" placeholder="24 / 26 / 28"></label></div><div class="two"><label>Quantity (pieces)<input name="qty" type="number" min="1" step="1" required></label><label>Reference<input name="reference" placeholder="MO / invoice / dispatch / GRN"></label></div><label>Reason / notes<input name="reason" required placeholder="Source document or adjustment reason"></label><button class="primary">Post stock movement</button><p class="hint">Use the same style, colour and size spelling consistently. Stock entries are device-local until the final secure shared database phase. Do not post a dispatch here if the dispatch module has already posted the same stock issue.</p></form>')+
 card('Available stock by style, colour & size','Saleable quantity excludes customer returns awaiting inspection.',rows.length?'<div class="tablewrap" style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr><th>Style</th><th>Colour</th><th>Size</th><th>Available</th><th>Quarantine</th><th>Movements</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.style)+'</td><td>'+esc(r.colour||'—')+'</td><td>'+esc(r.size||'—')+'</td><td><b>'+r.available+'</b></td><td>'+r.quarantined+'</td><td>'+r.moves+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty compact">No garment stock movements yet. Enter opening balances after physically counting stock, then record production receipts and dispatch issues.</div>')+
 card('Return inspection & release','Returned garments are not saleable until checked.',garmentStockMoves.filter(m=>m.type==='Customer return'&&m.status!=='released').length?garmentStockMoves.filter(m=>m.type==='Customer return'&&m.status!=='released').map(m=>'<div class="line"><div><b>'+esc(m.style)+' · '+esc(m.colour||'')+' · '+esc(m.size||'')+'</b><small>'+m.qty+' pcs · '+esc(m.date)+' · '+esc(m.reason)+'</small></div><button class="secondary" data-release-return="'+esc(m.id)+'">QC passed — release</button></div>').join(''):'<div class="empty compact">No customer returns awaiting inspection.</div>')+
 inventoryMigrationPreviewCard()+card('Stock movement history',garmentStockMoves.length+' entries · newest first',garmentStockMoves.length?garmentStockMoves.slice().reverse().slice(0,100).map(m=>'<div class="line"><div><b>'+esc(m.type)+' · '+esc(m.style)+'</b><small>'+esc(m.date)+' · '+esc(m.colour||'')+' · '+esc(m.size||'')+' · '+esc(m.reference||'No reference')+'</small><small>'+esc(m.reason||'')+(m.status==='released'?' · QC released':'')+'</small></div><strong>'+(['Dispatch / sale issue','Stock adjustment out'].includes(m.type)?'−':'+')+m.qty+'</strong></div>').join(''):'<div class="empty compact">No movement history.</div>');
}
function bindGarmentStock(){
 const f=document.getElementById('garment-stock-form');if(f)f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));d.style=String(d.style||'').trim();d.colour=String(d.colour||'').trim();d.size=String(d.size||'').trim();d.qty=Number(d.qty);if(!d.style||!d.date||!Number.isInteger(d.qty)||d.qty<1||!String(d.reason||'').trim()){alert('Enter style, date, whole-piece quantity and reason.');return;}if(d.type==='Customer return')d.status='quarantine';const key=[d.style,d.colour,d.size].join('¦');const current=stockBalanceRows().find(r=>[r.style,r.colour,r.size].join('¦')===key);const available=current?current.available:0;if(['Dispatch / sale issue','Stock adjustment out'].includes(d.type)&&d.qty>available){alert('Not enough saleable stock. Available: '+available+' pieces.');return;}d.id='GSM-'+Date.now()+'-'+Math.floor(Math.random()*10000);d.createdAt=new Date().toISOString();garmentStockMoves.push(d);localStorage.setItem(GARMENT_STOCK_KEY,JSON.stringify(garmentStockMoves));render();};
 document.querySelectorAll('[data-release-return]').forEach(b=>b.onclick=()=>{const m=garmentStockMoves.find(x=>x.id===b.dataset.releaseReturn);if(!m||m.type!=='Customer return'||m.status==='released')return;if(!confirm('Confirm this returned quantity passed inspection and is saleable?'))return;m.status='released';m.releasedAt=new Date().toISOString();localStorage.setItem(GARMENT_STOCK_KEY,JSON.stringify(garmentStockMoves));render();});
}


