function arReminderStage(v){let a=arAge(v);if(a===-3)return '3 days before due';if(a===0)return 'Due today';if(a===3)return '3 days overdue';if(a===7)return '7 days overdue';if(a>7&&(a-7)%15===0)return '15-day overdue follow-up';return '';}
function collectionReminderPage(){let paused=arOpen().filter(v=>arCaseFor(v).status!=='active'),os=arOpen().filter(v=>arCaseFor(v).status==='active');return '<div class="heading"><div><small>COLLECTION FOLLOW-UP</small><h2>Collection reminders</h2></div><span class="tag">MANUAL SHARE</span></div>'+card('Reminder schedule','3 days before due · due date · 3 days overdue · 7 days overdue · then every 15 days. Only scheduled dates are highlighted.','<div class="featurelist"><div><b>3 days before due</b><small>Friendly advance reminder</small></div><div><b>Due date</b><small>Payment due today</small></div><div><b>3 and 7 days overdue</b><small>Follow-up</small></div><div><b>Every 15 days after day 7</b><small>Further overdue follow-up</small></div></div>')+card('Open invoice reminders','WhatsApp opens with a prepared message. You must press Send. Disputed and on-hold invoices are paused.',os.map(v=>{let a=arAge(v),stage=arReminderStage(v)|| (a<0?'Upcoming in '+Math.abs(a)+' days':a+' days overdue');return '<div class="line"><div><b>'+esc(v.buyer_name)+' · '+esc(v.invoice_no)+'</b><small>Due '+esc(arDue(v))+' · '+(a>0?a+' days overdue':a===0?'Due today':Math.abs(a)+' days remaining')+' · '+arFmt(arBal(v))+'</small><small>'+esc(stage)+'</small></div><button class="secondary" data-ar-remind="'+esc(v.id)+'" data-stage="'+esc(stage)+'">Share reminder</button></div>'}).join('')||'<div class="empty">No open invoices.</div>')+card('Reminder history','Recorded share actions.',arReminders.slice().reverse().map(r=>'<div class="line"><b>'+esc(r.customer)+' · '+esc(r.invoiceNo)+'</b><small>'+esc(r.date)+' · '+esc(r.stage)+'</small></div>').join('')||'<div class="empty">No reminders yet.</div>')+'<p class="hint">'+paused.length+' disputed/on-hold invoice(s) are excluded from reminders. Automatic WhatsApp remains disabled until Meta onboarding, approved templates, customer opt-in and secure server-side balance sync are ready.</p>'}
