 const s=document.getElementById('mfg-sample');if(s)s.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(s)),style=String(d.style||'').trim();if(!style){alert('Enter a style number.');return;}const same=(mfg.samples||[]).filter(x=>String(x.style||'').trim().toLowerCase()===style.toLowerCase()),version=same.reduce((n,x)=>Math.max(n,Number(x.version||1)),0)+1,record={...d,id:'SMP-'+Date.now(),style,version,versionLabel:'V'+version,status:'Draft',previousVersionId:same.length?same.sort((a,b)=>Number(b.version||1)-Number(a.version||1))[0].id:'',createdAt:new Date().toISOString(),history:[{status:'Draft',date:new Date().toISOString()}]};mfg.samples.push(record);saveMfg();render();};
 document.querySelectorAll('[data-sample-submit]').forEach(b=>b.onclick=()=>{const x=mfg.samples.find(s=>s.id===b.dataset.sampleSubmit);if(!x||x.status!=='Draft'){alert('Only a draft sample can be submitted.');return;}x.status='Submitted for approval';x.history=x.history||[];x.history.push({status:x.status,date:new Date().toISOString()});saveMfg();render();});
 document.querySelectorAll('[data-sample-approve]').forEach(b=>b.onclick=()=>{const x=mfg.samples.find(s=>s.id===b.dataset.sampleApprove);if(!x||x.status!=='Submitted for approval'){alert('Only a submitted sample can be approved.');return;}if(!confirm('Approve '+x.style+' '+(x.versionLabel||'version')+' as the production reference? The approved version will be locked.'))return;x.status='Approved';x.approvedAt=new Date().toISOString();x.approvedBy='Local user — identity not verified';x.history=x.history||[];x.history.push({status:x.status,date:x.approvedAt});saveMfg();render();});
 document.querySelectorAll('[data-sample-revise]').forEach(b=>b.onclick=()=>{const x=mfg.samples.find(s=>s.id===b.dataset.sampleRevise);if(!x)return;const style=x.style,type=x.type,notes=prompt('Revision notes for '+style+' '+(x.versionLabel||'version')+':',x.notes||'');if(notes===null)return;const same=mfg.samples.filter(y=>String(y.style||'').trim().toLowerCase()===String(style).trim().toLowerCase()),version=same.reduce((n,y)=>Math.max(n,Number(y.version||1)),0)+1,record={id:'SMP-'+Date.now(),style,type,notes,version,versionLabel:'V'+version,previousVersionId:x.id,status:'Draft',createdAt:new Date().toISOString(),history:[{status:'Draft',date:new Date().toISOString(),notes:'Revision of '+(x.versionLabel||'previous version')}]};mfg.samples.push(record);saveMfg();render();});
